package com.jotafy.app;
import android.content.*;import android.security.keystore.*;import android.util.Base64;import javax.crypto.*;import javax.crypto.spec.GCMParameterSpec;import java.security.*;import java.net.*;import java.io.*;import org.json.*;
final class Store {
 static android.content.SharedPreferences prefs(Context c){return c.getSharedPreferences("jotafy",0);}
 static SecretKey key() throws Exception {KeyStore ks=KeyStore.getInstance("AndroidKeyStore");ks.load(null);if(!ks.containsAlias("jotafy")){KeyGenerator g=KeyGenerator.getInstance("AES","AndroidKeyStore");g.init(new KeyGenParameterSpec.Builder("jotafy",KeyProperties.PURPOSE_ENCRYPT|KeyProperties.PURPOSE_DECRYPT).setBlockModes("GCM").setEncryptionPaddings("NoPadding").build());g.generateKey();}return (SecretKey)ks.getKey("jotafy",null);}
 static void save(Context c,String url,String token)throws Exception {URI u=new URI(url);if(!"https".equals(u.getScheme())||u.getHost()==null||u.getUserInfo()!=null||u.getQuery()!=null||u.getFragment()!=null||!u.getPath().matches("/?"))throw new Exception("Use a URL HTTPS do Worker, sem caminho.");if(!token.matches("[a-fA-F0-9]{64}"))throw new Exception("A chave deve conter 64 caracteres hexadecimais.");Cipher x=Cipher.getInstance("AES/GCM/NoPadding");x.init(Cipher.ENCRYPT_MODE,key());prefs(c).edit().putString("url",url.replaceAll("/$","")).putString("iv",Base64.encodeToString(x.getIV(),0)).putString("secret",Base64.encodeToString(x.doFinal(token.getBytes("UTF-8")),0)).remove("cursor").commit();}
 static JSONObject load(Context c,int days,boolean events)throws Exception {String url=prefs(c).getString("url","");if(url.isEmpty())throw new Exception("Configure a conexão primeiro.");Cipher x=Cipher.getInstance("AES/GCM/NoPadding");x.init(Cipher.DECRYPT_MODE,key(),new GCMParameterSpec(128,Base64.decode(prefs(c).getString("iv",""),0)));String token=new String(x.doFinal(Base64.decode(prefs(c).getString("secret",""),0)),"UTF-8");String cursor=events&&prefs(c).contains("cursor")?"&after="+prefs(c).getLong("cursor",0):"";HttpURLConnection h=(HttpURLConnection)new URL(url+"/dashboard?days="+days+cursor).openConnection();h.setInstanceFollowRedirects(false);h.setConnectTimeout(15000);h.setReadTimeout(15000);h.setRequestProperty("Authorization","Bearer "+token);try{int status=h.getResponseCode();if(status!=200)throw new Exception(status==401?"Chave de acesso inválida.":"Servidor indisponível (HTTP "+status+").");try(InputStream in=h.getInputStream();ByteArrayOutputStream b=new ByteArrayOutputStream()){byte[] data=new byte[4096];int n;while((n=in.read(data))!=-1){b.write(data,0,n);if(b.size()>1000000)throw new Exception("Resposta muito grande.");}return new JSONObject(b.toString("UTF-8"));}}finally{h.disconnect();}}
 static String label(String s){switch(s){case "approved":return "Venda aprovada";case "pix_generated":return "Pix gerado";case "refunded":return "Venda reembolsada";case "charged_back":return "Contestação";case "rejected":return "Pagamento recusado";case "cancelled":return "Pagamento cancelado";case "pix":return "Pix";case "credit_card":return "Cartão de crédito";case "debit_card":return "Cartão de débito";default:return "Não informado";}}
 static String money(long cents){return java.text.NumberFormat.getCurrencyInstance(new java.util.Locale("pt","BR")).format(cents/100.0);}
}
